probe() {
  g="${1%%:*}"; d="${1#*:}"
  r=$(curl -s -m 20 -L --max-redirs 3 -A "torumata-probe/0.1 (+https://torumata.com/probe)" "https://$d/robots.txt" | grep -c -i "cloudflare managed content")
  echo "$g|$d|robots_M_B|$r"
  for ua in "L3|torumata-probe/0.1 (+https://torumata.com/probe)" "L5|torumata-ai-train/0.1 (+https://torumata.com/probe)" "L4a|Mozilla/5.0 AppleWebKit/537.36 (KHTML, like Gecko; compatible; GPTBot/1.2; +https://openai.com/gptbot)" "L4c|Mozilla/5.0 AppleWebKit/537.36 (KHTML, like Gecko); compatible; ChatGPT-User/1.0; +https://openai.com/bot" "L4g|Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)"; do
    k="${ua%%|*}"; u="${ua#*|}"
    code=$(curl -s -m 20 -L --max-redirs 3 -A "$u" -o /dev/null -w "%{http_code}" "https://$d/")
    echo "$g|$d|$k|$code"
  done
}
export -f probe
for x in $D; do echo "$x"; done | xargs -P 8 -I{} bash -c 'probe "$@"' _ {} >> "$OUT"
echo "hotovo: $OUT ($(wc -l < "$OUT") řádků)"; echo "souhrn:"; awk -F'|' 'NR>1 {k=$1"|"$3; n[k]++; if(($3=="robots_M_B" && $4>0) || ($3!="robots_M_B" && $4!="200")) f[k]++} END {for (k in n) printf "%s %d/%d\n", k, f[k]+0, n[k]}' "$OUT" | sort
